package com.memetrade.txsigner.testsupport;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import java.io.IOException;
import java.io.UncheckedIOException;
import java.nio.file.Path;
import java.util.HexFormat;

/**
 * TEST ONLY: reader of the common Solana vectors of the api and the TxSigner
 * ({@code src/test/resources/solana-vectors/vectors.json}). They are generated by the Solana SDK in the TEST scope of
 * the api (the TxSigner bans the SDK in every scope), and the two files must stay equal ({@code SolanaVectorFilesTest}).
 */
public final class SolanaVectors {

    public static final Path FILE = Path.of("src", "test", "resources", "solana-vectors", "vectors.json");
    public static final Path API_FILE =
            Path.of("..", "api", "src", "test", "resources", "solana-vectors", "vectors.json");

    private SolanaVectors() {}

    public static JsonNode load() {
        try {
            return new ObjectMapper().readTree(FILE.toFile());
        } catch (IOException failure) {
            throw new UncheckedIOException(failure);
        }
    }

    public static byte[] hex(String value) {
        return HexFormat.of().parseHex(value);
    }

    public static JsonNode message(String name) {
        for (JsonNode message : load().path("messages")) {
            if (message.path("name").asText().equals(name)) {
                return message;
            }
        }
        throw new IllegalArgumentException("No vector " + name);
    }
}
